script:
(function () {
  'use strict';
  // 20-year vs 30-year mortgage with the payment difference invested.
  //   Payment M = B * i / (1 - (1 + i)^-n), i = rate / 12 (M = B / n at 0%).
  //   Both households spend the same cash each month. Years 1-20: each pays the 20-year payment's
  //   worth; the 30-year borrower invests (M20 - M30). Years 21-30: the 20-year loan is gone, so that
  //   borrower invests M30 while the other keeps paying M30. Deposits at month end, growing at the
  //   monthly equivalent of the annual return, (1 + r)^(1/12) - 1. At the horizon, tax on gains is
  //   taken as if the investments were sold. Net worth lead = (fund - loan balance) of the 30-year
  //   plan minus the same for the 20-year plan (the home's value is the same in both and cancels).
  //   Break-even return: bisection on r between -20% and 50% for a lead of zero.
  // Verified in Node (scratchpad mtg6/tests/tvt.test.js): $300,000 at 6% for 20 years = $2,149.29,
  //   at 6.5% for 30 years = $1,896.20; 30-year balance after 240 payments $166,995.85 (all closed
  //   form); invested difference of $253.09/mo for 20 years at 7% = $128,451.93 (annuity formula) and
  //   at 0% = $60,741.39 (240 x difference); with both loans at 6% and a 6.1678% return (the loans'
  //   effective annual rate) the two plans finish level at year 30 (lead -$0.01), and the break-even
  //   solver returns 6.1678%; 0% rates, blank and negative inputs never reach the page as NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- pure ---
  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  // o: loan, r20, r30, ret (annual %), years (horizon), tax (% on gains)
  function compare(o) {
    var p20 = payment(o.loan, o.r20, 240), p30 = payment(o.loan, o.r30, 360);
    var g = Math.pow(1 + o.ret / 100, 1 / 12) - 1;
    var b20 = o.loan, b30 = o.loan, f20 = 0, f30 = 0, c20 = 0, c30 = 0, i20 = 0, i30 = 0, rows = [];
    var budget = Math.max(p20, p30);
    function after(f, c) { var gain = f - c; return gain > 0 ? f - gain * o.tax / 100 : f; }
    for (var m = 1; m <= o.years * 12; m++) {
      var pay20 = 0, pay30 = 0;
      if (b20 > 0.005) { var int20 = b20 * o.r20 / 1200; pay20 = Math.min(p20, b20 + int20); b20 = b20 + int20 - pay20; i20 += int20; }
      else b20 = 0;
      if (b30 > 0.005) { var int30 = b30 * o.r30 / 1200; pay30 = Math.min(p30, b30 + int30); b30 = b30 + int30 - pay30; i30 += int30; }
      else b30 = 0;
      // Same monthly budget on both sides: the larger payment in years 1-20, the 30-year payment after.
      var spend = m <= 240 ? budget : p30;
      var d20 = Math.max(0, spend - pay20), d30 = Math.max(0, spend - pay30);
      f20 = f20 * (1 + g) + d20; c20 += d20;
      f30 = f30 * (1 + g) + d30; c30 += d30;
      if (m % 12 === 0 || m === o.years * 12) {
        var n20 = after(f20, c20) - b20, n30 = after(f30, c30) - b30;
        rows.push({ year: Math.ceil(m / 12), b20: b20, f20: after(f20, c20), b30: b30, f30: after(f30, c30), lead: n30 - n20 });
      }
    }
    var last = rows[rows.length - 1];
    return { p20: p20, p30: p30, b20: b20, b30: b30, f20: last.f20, f30: last.f30, c20: c20, c30: c30,
             i20: i20, i30: i30, lead: last.lead, rows: rows };
  }

  // Annual return (%) at which the two plans finish level, or NaN if none in -20%..50%.
  function breakEven(o) {
    function f(r) { return compare(Object.assign({}, o, { ret: r })).lead; }
    var lo = -20, hi = 50, flo = f(lo), fhi = f(hi);
    if (flo === 0) return lo;
    if (flo * fhi > 0) return NaN;
    for (var k = 0; k < 80; k++) {
      var mid = (lo + hi) / 2, fm = f(mid);
      if ((fm > 0) === (fhi > 0)) { hi = mid; fhi = fm; } else { lo = mid; }
    }
    return (lo + hi) / 2;
  }
  // --- end pure ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function cell(row, text) { var td = document.createElement('td'); td.textContent = text; row.appendChild(td); }
  function signed(v) { return (v >= 0 ? '+' : '−') + money.format(Math.abs(v)); }

  var OUT = ['tvtLead', 'tvtPay20', 'tvtPay30', 'tvtDiff', 'tvtNet20', 'tvtNet30', 'tvtBal20', 'tvtBal30', 'tvtFund20', 'tvtFund30',
             'tvtInt20', 'tvtInt30', 'tvtBreak', 'tvtVerdict', 'tvtHorizonOut'];
  function clearAll() { OUT.forEach(function (id) { setText(id, '–'); }); el('tvtSchedule').textContent = ''; }

  function update() {
    var o = { loan: read('tvtLoan', NaN), r20: read('tvtRate20', NaN), r30: read('tvtRate30', NaN), ret: read('tvtReturn', NaN),
              years: read('tvtYears', NaN), tax: read('tvtTax', 0) };
    var msg = '';
    if (isNaN(o.loan) || o.loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if ([o.r20, o.r30].some(function (v) { return isNaN(v) || v < 0 || v > 30; })) msg = 'Enter interest rates from 0% to 30%.';
    else if (isNaN(o.ret) || o.ret < -20 || o.ret > 50) msg = 'Enter an investment return from -20% to 50%.';
    else if (isNaN(o.years) || o.years < 1 || o.years > 30 || o.years % 1 !== 0) msg = 'Enter a whole number of years from 1 to 30.';
    else if (isNaN(o.tax) || o.tax < 0 || o.tax > 60) msg = 'Enter a tax rate on gains from 0% to 60%.';
    el('tvtError').hidden = !msg;
    el('tvtError').textContent = msg;
    if (msg) { clearAll(); return; }

    var r = compare(o);
    var net20 = r.f20 - r.b20, net30 = r.f30 - r.b30;
    setText('tvtHorizonOut', String(o.years));
    setText('tvtLead', (r.lead >= 0 ? '30-year by ' : '20-year by ') + money.format(Math.abs(r.lead)));
    setText('tvtPay20', cents.format(r.p20));
    setText('tvtPay30', cents.format(r.p30));
    setText('tvtDiff', cents.format(r.p20 - r.p30) + ' a month');
    setText('tvtNet20', signed(net20));
    setText('tvtNet30', signed(net30));
    setText('tvtBal20', money.format(r.b20));
    setText('tvtBal30', money.format(r.b30));
    setText('tvtFund20', money.format(r.f20));
    setText('tvtFund30', money.format(r.f30));
    var full = compare(Object.assign({}, o, { years: 30 }));
    setText('tvtInt20', money.format(full.i20));
    setText('tvtInt30', money.format(full.i30));
    var be = breakEven(o);
    setText('tvtBreak', isNaN(be) ? 'None between −20% and 50%' : be.toFixed(2) + '% a year');
    var verdict;
    if (r.p20 <= r.p30) verdict = 'The 20-year payment is not higher than the 30-year payment here, so there is no difference to invest and the shorter loan wins on cost.';
    else if (Math.abs(r.lead) < 1) verdict = 'After ' + o.years + ' years the two plans finish level.';
    else if (r.lead > 0) verdict = 'Taking the 30-year loan and investing the ' + cents.format(r.p20 - r.p30) + ' monthly difference leaves you ' + money.format(r.lead) + ' better off after ' + o.years + ' years, if the investments earn ' + o.ret + '% a year.' + (isNaN(be) ? '' : ' Below about ' + be.toFixed(2) + '% the 20-year loan comes out ahead.');
    else verdict = 'The 20-year loan leaves you ' + money.format(-r.lead) + ' better off after ' + o.years + ' years at a ' + o.ret + '% return.' + (isNaN(be) ? '' : ' The investments would need to earn more than about ' + be.toFixed(2) + '% a year for the 30-year plan to win.');
    setText('tvtVerdict', verdict);

    var body = el('tvtSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      cell(tr, String(row.year));
      cell(tr, money.format(row.b20));
      cell(tr, money.format(row.f20));
      cell(tr, money.format(row.b30));
      cell(tr, money.format(row.f30));
      cell(tr, (row.lead >= 0 ? '30-yr +' : '20-yr +') + money.format(Math.abs(row.lead)));
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('tvtForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
